const current = $('Aggregate Weekly Statistics1').first().json;
const responseItems = $input.all().map(item => item.json);
const lastMonday = new Date(Date.parse(`${current.week_start}T00:00:00.000Z`) - 7 * 86400000).toISOString().slice(0, 10);
const key = `${current.repository}#${lastMonday}`;
const matching = responseItems.filter(row => row.report_key === key);
if (matching.length > 1) throw new Error(`Duplicate weekly records for ${key}`);

const names = ['issues_created', 'issues_closed', 'prs_created', 'prs_merged'];
const previous = matching[0] ?? null;
const delta = {};
const previousValues = {};
const comparisonAvailable = previous !== null;

for (const name of names) {
  const now = Number(current[name]);
  if (!Number.isFinite(now)) throw new Error(`Invalid current value: ${name}`);
  if (!comparisonAvailable) {
    previousValues[name] = null;
    delta[name] = null;
  } else {
    const then = Number(previous[name]);
    if (previous[name] == null || !Number.isFinite(then)) throw new Error(`Invalid previous ${name}`);
    previousValues[name] = then;
    delta[name] = now - then;
  }
}
const previousTypes = comparisonAvailable ? JSON.parse(previous.by_type_json || '{}') : null;
const typeDelta = {};
for (const category of ['bug', 'task', 'feature', 'unknown']) {
  typeDelta[category] = comparisonAvailable
    ? Number(current.by_type[category] ?? 0) - Number(previousTypes[category] ?? 0)
    : null;
}
return [{json: {
  ...current,
  comparison_available: comparisonAvailable,
  previous_week_start: lastMonday,
  previous: previousValues,
  delta,
  previous_by_type: previousTypes,
  type_delta: typeDelta
}}];

