const period = $('Prepare Weekly Date Range').first().json;
const queries = [
  {node: 'Search Created Issues', field: 'created_at'},
  {node: 'Search Closed Issues', field: 'closed_at'},
  {node: 'Search Created PRs', field: 'created_at'},
  {node: 'Search Merged PRs', field: 'pull_request.merged_at'},
];

const results = queries.map(({node, field}) => {
  const response = $(node).first().json;
  if (!Array.isArray(response.items) || typeof response.total_count !== 'number') {
    throw new Error(`${node}: unexpected GitHub Search API response`);
  }
  if (response.incomplete_results) {
    throw new Error(`${node}: GitHub reports incomplete search results`);
  }
  if (response.total_count > 100) {
    throw new Error(`${node}: ${response.total_count} results exceed page limit 100; add pagination`);
  }
  // Search filters dates by day. Enforce exact UTC boundaries here.
  const items = response.items.filter(item => {
    const value = field === 'pull_request.merged_at'
      ? item.pull_request?.merged_at
      : item[field];
    if (!value) return false;
    return value >= period.start_iso && value < period.end_iso;
  });
  return items;
});

const [createdIssues, closedIssues, createdPRs, mergedPRs] = results;
const byType = { bug: 0, task: 0, feature: 0, unknown: 0 };
const byAuthor = {};

for (const issue of createdIssues) {
  const names = new Set((issue.labels || []).map(l =>
    typeof l === 'string' ? l : l.name).filter(Boolean));
  const assigned = ['bug', 'task', 'feature'].filter(t => names.has(t));
  const type = names.has('needs-triage') || assigned.length !== 1
    ? 'unknown' : assigned[0];
  byType[type]++;
  const author = issue.user?.login || 'unknown';
  byAuthor[author] = (byAuthor[author] || 0) + 1;
}

return [{json: {
  repository: period.repository,
  week_start: period.week_start,
  week_end: period.week_end,
  week_end_exclusive: period.week_end_exclusive,
  is_test_override: period.is_test_override,
  issues_created: createdIssues.length,
  issues_closed: closedIssues.length,
  prs_created: createdPRs.length,
  prs_merged: mergedPRs.length,
  by_type: byType,
  by_author: Object.entries(byAuthor)
    .map(([author, issues_created]) => ({author, issues_created}))
    .sort((a,b) => b.issues_created-a.issues_created || a.author.localeCompare(b.author)),
  sample_issue_numbers: createdIssues.map(i => i.number),
}}];

// Optional test override: set to '2026-11-09' or '2026-11-16'
const manualWeekStart = '';
const repository = 'nullifierx1/n8n-code-review-test';

const today = new Date();
const utcToday = new Date(Date.UTC(
  today.getUTCFullYear(), today.getUTCMonth(), today.getUTCDate()
));
const daysAfterMonday = (utcToday.getUTCDay() + 6) % 7;
const currentMonday = new Date(utcToday);
currentMonday.setUTCDate(currentMonday.getUTCDate() - daysAfterMonday);

let start;
if (manualWeekStart) {
  if (!/^\d{4}-\d{2}-\d{2}$/.test(manualWeekStart)) {
    throw new Error('manualWeekStart must use YYYY-MM-DD');
  }
  start = new Date(`${manualWeekStart}T00:00:00.000Z`);
  if (Number.isNaN(start.getTime()) || start.getUTCDay() !== 1 ||
      start.toISOString().slice(0, 10) !== manualWeekStart) {
    throw new Error('manualWeekStart must be a valid Monday');
  }
} else {
  start = new Date(currentMonday);
  start.setUTCDate(start.getUTCDate() - 7);
}

const end = new Date(start);
end.setUTCDate(end.getUTCDate() + 7);
const sunday = new Date(end);
sunday.setUTCDate(sunday.getUTCDate() - 1);
const format = d => d.toISOString().slice(0, 10);

return [{ json: {
  repository,
  week_start: format(start),
  week_end: format(sunday),
  week_end_exclusive: format(end),
  start_iso: start.toISOString(),
  end_iso: end.toISOString(),
  github_date_range: `${format(start)}..${format(sunday)}`,
  is_test_override: Boolean(manualWeekStart),
}}];

const s = $('Calculate Weekly Delta').first().json;
const rawComment = $('AI Weekly Commentary').first().json;
const comment = String(rawComment.text ?? rawComment.output ?? rawComment.response ?? '').trim();
if (!comment) throw new Error('Basic LLM Chain returned an empty AI commentary');
const esc = v => String(v ?? '').replace(/[&<>"']/g, c => ({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const count = x => {
  if (!Number.isInteger(x) || x < 0) throw new Error(`Invalid count ${x}`);
  return String(x);
};
const categories = [['bug','Bug'],['task','Task'],['feature','Feature'],['unknown','Unknown']];
const row = (label, value) => `<tr><td style="padding:9px;border-bottom:1px solid #e2e8f0">${esc(label)}</td><td style="padding:9px;text-align:right;border-bottom:1px solid #e2e8f0">${esc(value)}</td></tr>`;
const categoryRows = categories.map(([key,label]) => row(label,count(s.by_type[key] ?? 0))).join('');
const authors = (s.by_author ?? []).map(a => row(a.author,count(a.issues_created))).join('') || '<tr><td colspan="2" style="padding:9px">No authors this week</td></tr>';
const metrics = [['Created Issues','issues_created'],['Closed Issues','issues_closed'],['Created PRs','prs_created'],['Merged PRs','prs_merged']];
const diff = n => n === null ? 'N/A' : n > 0 ? `+${n}` : String(n);
const compRows = metrics.map(([label,key]) => `<tr>
<td style="padding:9px;border-bottom:1px solid #e2e8f0">${esc(label)}</td>
<td style="padding:9px;text-align:right;border-bottom:1px solid #e2e8f0">${s.comparison_available ? count(s.previous[key]) : 'N/A'}</td>
<td style="padding:9px;text-align:right;border-bottom:1px solid #e2e8f0">${count(s[key])}</td>
<td style="padding:9px;text-align:right;border-bottom:1px solid #e2e8f0">${esc(diff(s.delta[key]))}</td>
</tr>`).join('');
const title = `GitHub Weekly Report | ${s.week_start} - ${s.week_end}`;
const html = `<!DOCTYPE html><html><head><meta charset="UTF-8"></head><body style="margin:0;padding:24px;background:#f5f7fa;font-family:Arial,Helvetica,sans-serif;color:#202939"><div style="max-width:650px;margin:auto;padding:24px;background:#fff;border:1px solid #e2e8f0;border-radius:10px">
<h1 style="font-size:24px;margin:0 0 6px">GitHub Weekly Report</h1><p style="color:#526177;margin:0 0 20px">${esc(s.repository)}<br>Week: ${esc(s.week_start)} - ${esc(s.week_end)}</p>
<h2 style="font-size:18px">Summary</h2><table style="border-collapse:collapse;width:100%;font-size:14px"><tbody>${metrics.map(([label,key])=>row(label,count(s[key]))).join('')}</tbody></table>
<h2 style="font-size:18px;margin-top:24px">Weekly Comparison</h2><p style="color:#526177;font-size:12px">Previous week starts: ${esc(s.previous_week_start)}${!s.comparison_available?' — no previous record in Data Table':''}</p>
<table style="border-collapse:collapse;width:100%;font-size:14px"><thead><tr style="background:#eef2f7"><th style="padding:9px;text-align:left">Metric</th><th style="padding:9px;text-align:right">Previous</th><th style="padding:9px;text-align:right">Current</th><th style="padding:9px;text-align:right">Δ</th></tr></thead><tbody>${compRows}</tbody></table>
<h2 style="font-size:18px;margin-top:24px">Created Issues by type</h2><table style="border-collapse:collapse;width:100%;font-size:14px"><thead><tr style="background:#eef2f7"><th style="padding:9px;text-align:left">Type</th><th style="padding:9px;text-align:right">Count</th></tr></thead><tbody>${categoryRows}</tbody></table>
<h2 style="font-size:18px;margin-top:24px">Created Issues by author</h2><table style="border-collapse:collapse;width:100%;font-size:14px"><thead><tr style="background:#eef2f7"><th style="padding:9px;text-align:left">Author</th><th style="padding:9px;text-align:right">Issues</th></tr></thead><tbody>${authors}</tbody></table>
<h2 style="font-size:18px;margin-top:24px">AI-комментарий недели</h2><p style="font-size:14px;line-height:1.55">${esc(comment).replace(/\n/g,'<br>')}</p>
${s.is_test_override?'<p style="font-size:12px;color:#7b5b22;margin-top:18px">Manual test: selected reporting week was overridden.</p>':''}
<p style="font-size:12px;color:#667085;margin-top:24px">Generated by n8n using GitHub API and GPT-5 via VseLLM.</p></div></body></html>`;
return [{json:{...s,ai_comment:comment,email_subject:title,html}}];
